GP_CUDA = '// Cluster glue for the decode layer (P7): one thread-block cluster of C CTAs per token. Each CTA reads\n// only its 1/C slice of the row (S6\'s Triton glue has every CTA read the whole row, so at S split\n// partials one SM\'s L2 bandwidth bounds it), and the row\'s norm partials meet through distributed\n// shared memory: each CTA pushes its partial sums into every CTA of the cluster, one cluster barrier,\n// then every CTA finishes its slice from the same C partials in the same order.\n//\n// boundary_cl: stream\' = alpha * stream + beta * rmsnorm(branch [* postw]); out = rmsnorm(stream\') * prew.\n//   ROUNDS 2: exact two-pass form (|stream\'|^2 summed after the branch norm is known).\n//   ROUNDS 1: one barrier; |stream\'|^2 = sum (a s)^2 + 2 r sum (a s)(b br) + r^2 sum (b br)^2, r = branch inv.\n// route_cl: x = rmsnorm(pooler) * prew (BF16); logits = sum of router hi + lo rows; sigmoid(logit/sqrt(32)),\n//   top-8 of sigmoid + bias (ties to the lower expert), weights = picked sigmoids / their sum, local ids.\n// Both release dependents at entry, load their weight vectors, then griddepcontrol.wait before any\n// read of the producer\'s output; launched with programmatic stream serialization.\n#include <cuda_runtime.h>\n#include <cuda_bf16.h>\n#include <cooperative_groups.h>\n#include <stdint.h>\n#include <stdexcept>\n\nnamespace cg = cooperative_groups;\n\nnamespace glue_cl {\n\n__device__ __forceinline__ void pdl_release() {\n#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 900\n  asm volatile("griddepcontrol.launch_dependents;" ::: "memory");\n#endif\n}\n__device__ __forceinline__ void pdl_wait() {\n#if defined(__CUDA_ARCH__) && __CUDA_ARCH__ >= 900\n  asm volatile("griddepcontrol.wait;" ::: "memory");\n#endif\n}\n\n__device__ __forceinline__ float4 ld4(const void* base, int f32, long long off) {\n  if (f32) return *reinterpret_cast<const float4*>(static_cast<const float*>(base) + off);\n  const uint2 v = *reinterpret_cast<const uint2*>(static_cast<const __nv_bfloat16*>(base) + off);\n  return make_float4(__uint_as_float(v.x << 16), __uint_as_float(v.x & 0xffff0000u),\n                     __uint_as_float(v.y << 16), __uint_as_float(v.y & 0xffff0000u));\n}\n\n// Sum S split partials at one float4 position, all loads in flight (groups of 8).\n__device__ __forceinline__ float4 sum_splits(const void* P, int f32, int S, long long ps, long long off) {\n  float4 a = make_float4(0.f, 0.f, 0.f, 0.f);\n  for (int s0 = 0; s0 < S; s0 += 8) {\n    float4 z[8];\n#pragma unroll\n    for (int u = 0; u < 8; ++u) z[u] = (s0 + u < S) ? ld4(P, f32, (s0 + u) * ps + off) : make_float4(0.f, 0.f, 0.f, 0.f);\n#pragma unroll\n    for (int u = 0; u < 8; ++u) {\n      a.x += z[u].x; a.y += z[u].y; a.z += z[u].z; a.w += z[u].w;\n    }\n  }\n  return a;\n}\n\ntemplate <int K, int NT>\n__device__ __forceinline__ void block_sum(float (&v)[K], float* red) {\n  const int lane = threadIdx.x & 31, warp = threadIdx.x >> 5;\n#pragma unroll\n  for (int k = 0; k < K; ++k)\n#pragma unroll\n    for (int d = 16; d; d >>= 1) v[k] += __shfl_xor_sync(0xffffffffu, v[k], d);\n  if (lane == 0)\n#pragma unroll\n    for (int k = 0; k < K; ++k) red[warp * K + k] = v[k];\n  __syncthreads();\n#pragma unroll\n  for (int k = 0; k < K; ++k) {\n    float s = 0.f;\n#pragma unroll\n    for (int w = 0; w < NT / 32; ++w) s += red[w * K + k];\n    v[k] = s;\n  }\n}\n\n// Push this CTA\'s K partials into slot [rank] of every CTA\'s `slots` [C][K], then one cluster barrier;\n// returns the C partials summed in rank order (identical in every CTA).\ntemplate <int K, int C>\n__device__ __forceinline__ void cluster_sum(cg::cluster_group& cl, float (&v)[K], float* slots) {\n  const int rank = (int)cl.block_rank();\n  if (threadIdx.x < C) {\n    float* dst = cl.map_shared_rank(slots, (int)threadIdx.x);\n#pragma unroll\n    for (int k = 0; k < K; ++k) dst[rank * K + k] = v[k];\n  }\n  cl.sync();\n#pragma unroll\n  for (int k = 0; k < K; ++k) {\n    float s = 0.f;\n#pragma unroll\n    for (int r = 0; r < C; ++r) s += slots[r * K + k];\n    v[k] = s;\n  }\n}\n\nconstexpr int HID = 8192;\n\n// grid (C, T), cluster (C, 1, 1), NT threads; each thread owns HID / (C * NT) consecutive float4 groups.\ntemplate <int C, int NT, int ROUNDS>\n__global__ void __launch_bounds__(NT) boundary_cl(const void* __restrict__ P, int pf32, int S, long long ps, long long rs,\n                                                  int NB, const float* __restrict__ stream, float* __restrict__ sout,\n                                                  __nv_bfloat16* __restrict__ out, const float* __restrict__ postw,\n                                                  const float* __restrict__ alpha, const float* __restrict__ beta,\n                                                  const float* __restrict__ prew) {\n  constexpr int G = HID / (4 * C * NT);  // float4 groups per thread\n  static_assert(G >= 1 && HID % (4 * C * NT) == 0, "slice");\n  __shared__ float red[(NT / 32) * 4];\n  __shared__ float slots[2][C * 4];\n  pdl_release();\n  cg::cluster_group cl = cg::this_cluster();\n  const int rank = (int)cl.block_rank(), t = blockIdx.y, tid = threadIdx.x;\n  float4 a[G], b[G], w[G], q[G];\n#pragma unroll\n  for (int g = 0; g < G; ++g) {\n    const int j = (rank * NT * G + g * NT + tid) * 4;\n    a[g] = *reinterpret_cast<const float4*>(alpha + j);\n    b[g] = *reinterpret_cast<const float4*>(beta + j);\n    w[g] = *reinterpret_cast<const float4*>(prew + j);\n    q[g] = postw ? *reinterpret_cast<const float4*>(postw + j) : make_float4(1.f, 1.f, 1.f, 1.f);\n  }\n  pdl_wait();\n  float4 s[G], br[G];\n#pragma unroll\n  for (int g = 0; g < G; ++g) {\n    const int j = (rank * NT * G + g * NT + tid) * 4;\n    s[g] = *reinterpret_cast<const float4*>(stream + (long long)t * HID + j);\n    br[g] = j < NB ? sum_splits(P, pf32, S, ps, (long long)t * rs + j) : make_float4(0.f, 0.f, 0.f, 0.f);\n    br[g].x *= q[g].x; br[g].y *= q[g].y; br[g].z *= q[g].z; br[g].w *= q[g].w;\n  }\n  float inv_br, inv;\n  if (ROUNDS == 1) {\n    float v[4] = {0.f, 0.f, 0.f, 0.f};  // sum br^2, (a s)^2, (a s)(b br), (b br)^2\n#pragma unroll\n    for (int g = 0; g < G; ++g) {\n      const float bb[4] = {br[g].x, br[g].y, br[g].z, br[g].w}, ss[4] = {s[g].x, s[g].y, s[g].z, s[g].w};\n      const float aa[4] = {a[g].x, a[g].y, a[g].z, a[g].w}, be[4] = {b[g].x, b[g].y, b[g].z, b[g].w};\n#pragma unroll\n      for (int k = 0; k < 4; ++k) {\n        const float x = aa[k] * ss[k], y = be[k] * bb[k];\n        v[0] += bb[k] * bb[k]; v[1] += x * x; v[2] += x * y; v[3] += y * y;\n      }\n    }\n    block_sum<4, NT>(v, red);\n    cluster_sum<4, C>(cl, v, slots[0]);\n    inv_br = rsqrtf(v[0] / HID + 1e-8f);\n    inv = rsqrtf((v[1] + 2.f * inv_br * v[2] + inv_br * inv_br * v[3]) / HID + 1e-5f);\n#pragma unroll\n    for (int g = 0; g < G; ++g) {\n      s[g].x = a[g].x * s[g].x + b[g].x * (br[g].x * inv_br); s[g].y = a[g].y * s[g].y + b[g].y * (br[g].y * inv_br);\n      s[g].z = a[g].z * s[g].z + b[g].z * (br[g].z * inv_br); s[g].w = a[g].w * s[g].w + b[g].w * (br[g].w * inv_br);\n    }\n  } else {\n    float v[1] = {0.f};\n#pragma unroll\n    for (int g = 0; g < G; ++g) v[0] += br[g].x * br[g].x + br[g].y * br[g].y + br[g].z * br[g].z + br[g].w * br[g].w;\n    block_sum<1, NT>(v, red);\n    cluster_sum<1, C>(cl, v, slots[0]);\n    inv_br = rsqrtf(v[0] / HID + 1e-8f);\n    float u[1] = {0.f};\n#pragma unroll\n    for (int g = 0; g < G; ++g) {\n      s[g].x = a[g].x * s[g].x + b[g].x * (br[g].x * inv_br); s[g].y = a[g].y * s[g].y + b[g].y * (br[g].y * inv_br);\n      s[g].z = a[g].z * s[g].z + b[g].z * (br[g].z * inv_br); s[g].w = a[g].w * s[g].w + b[g].w * (br[g].w * inv_br);\n      u[0] += s[g].x * s[g].x + s[g].y * s[g].y + s[g].z * s[g].z + s[g].w * s[g].w;\n    }\n    __syncthreads();  // red reuse\n    block_sum<1, NT>(u, red);\n    cluster_sum<1, C>(cl, u, slots[1]);\n    inv = rsqrtf(u[0] / HID + 1e-5f);\n  }\n#pragma unroll\n  for (int g = 0; g < G; ++g) {\n    const int j = (rank * NT * G + g * NT + tid) * 4;\n    *reinterpret_cast<float4*>(sout + (long long)t * HID + j) = s[g];\n    __nv_bfloat162 o0 = __floats2bfloat162_rn(s[g].x * inv * w[g].x, s[g].y * inv * w[g].y);\n    __nv_bfloat162 o1 = __floats2bfloat162_rn(s[g].z * inv * w[g].z, s[g].w * inv * w[g].w);\n    uint2 ov = make_uint2(*reinterpret_cast<uint32_t*>(&o0), *reinterpret_cast<uint32_t*>(&o1));\n    *reinterpret_cast<uint2*>(out + (long long)t * HID + j) = ov;\n  }\n}\n\n// MoERouteMeta v1 (problems/muse_decode_layer/dev/nt1_branches/route_meta.h): per-call routing description\n// for the small-M MoE (tokens <= 32), written by route_cl\'s last-arriving cluster.\nstruct alignas(128) MoERouteMeta {\n  int32_t version, tokens, local_start, pairs;\n  int32_t count[32];\n  int32_t offset[33];\n  int32_t blocks8[32];\n  int32_t units13[33], units2[33];\n  int32_t token_local[32];\n  int32_t pair_of[256];  // sorted local position -> token*8+slot, -1 unused\n  int32_t pos_of[256];   // token*8+slot -> sorted local position, -1 remote\n};\nstatic_assert(sizeof(MoERouteMeta) == 2944, "MoERouteMeta v1");\n\n// nt1_branches/route_meta.cu.inc\'s make_route_meta body for one 256-thread CTA, reading local ids (-1 remote).\n__device__ __forceinline__ void write_route_meta(const int* __restrict__ lids, int M, int start, MoERouteMeta* dst) {\n  __shared__ int n[32], wc[8][32], off[32];\n  const int t = threadIdx.x, lane = t & 31, warp = t >> 5;\n  if (t < 32) n[t] = 0;\n  dst->pair_of[t] = -1;\n  dst->pos_of[t] = -1;\n  if (t < 32) dst->token_local[t] = 0;\n  __syncthreads();\n  const int e = t < M * 8 ? __ldcg(lids + t) : -1;\n  if (e >= 0) atomicAdd(n + e, 1);\n  __syncthreads();\n  if (warp == 0) {\n    const int count = n[lane], nb = (count + 7) / 8;\n    int p = count, u1 = nb * 512, u2 = nb * 256;\n#pragma unroll\n    for (int d = 1; d < 32; d <<= 1) {\n      const int a = __shfl_up_sync(~0u, p, d), b = __shfl_up_sync(~0u, u1, d), c = __shfl_up_sync(~0u, u2, d);\n      if (lane >= d) { p += a; u1 += b; u2 += c; }\n    }\n    off[lane] = p - count;\n    dst->count[lane] = count; dst->offset[lane] = p - count; dst->blocks8[lane] = nb;\n    dst->units13[lane + 1] = u1; dst->units2[lane + 1] = u2;\n    if (lane == 31) { dst->pairs = p; dst->offset[32] = p; }\n    if (lane == 0) { dst->version = 1; dst->tokens = M; dst->local_start = start; dst->units13[0] = dst->units2[0] = 0; }\n  }\n  wc[warp][lane] = 0;\n  __syncthreads();\n  const unsigned mk = __match_any_sync(~0u, e);\n  const int rnk = __popc(mk & ((1u << lane) - 1));\n  if (e >= 0 && rnk == 0) wc[warp][e] = __popc(mk);\n  __syncthreads();\n  if (t < 32) {\n    int sum = off[t];\n    for (int w = 0; w < 8; ++w) { const int v = wc[w][t]; wc[w][t] = sum; sum += v; }\n  }\n  __syncthreads();\n  if (e >= 0) { const int pos = wc[warp][e] + rnk; dst->pair_of[pos] = t; dst->pos_of[t] = pos; }\n  if (t < M) {\n    int cnt = 0;\n#pragma unroll\n    for (int q = 0; q < 8; ++q) cnt += __ldcg(lids + t * 8 + q) >= 0;\n    dst->token_local[t] = cnt;\n  }\n}\n\nconstexpr int DP = 4096;   // pooler width\nconstexpr int NE = 256;    // experts\n\n// Order-preserving integer image of a float (S6\'s key: larger float -> larger key; never 0 for a non-NaN).\n__device__ __forceinline__ uint32_t route_ord(float biased) {\n  const uint32_t bits = __float_as_uint(biased);\n  return (bits & 0x80000000u) ? ~bits : (bits ^ 0x80000000u);\n}\n\n// grid (C, T), cluster (C, 1, 1), NT threads. Pooler: HID-style float4 slices of DP / C columns.\n// Logits: CTA rank owns experts [rank * NE / C, ...); its sigmoids and keys go to rank 0\'s smem.\ntemplate <int C, int NT>\n__global__ void __launch_bounds__(NT) route_cl(const void* __restrict__ P, int pf32, int S, long long ps, long long rs,\n                                               const float* __restrict__ bias, const float* __restrict__ prew,\n                                               const int* __restrict__ lstart, __nv_bfloat16* __restrict__ X,\n                                               int* __restrict__ ids, float* __restrict__ wts, int* __restrict__ lids,\n                                               MoERouteMeta* __restrict__ meta, unsigned* __restrict__ arrive) {\n  constexpr int GP = DP / (4 * C * NT);   // pooler float4 groups per thread (0: some threads idle)\n  constexpr int EP = NE / C;              // experts per CTA\n  static_assert(DP % (4 * C) == 0 && NE % C == 0 && EP <= NT, "slice");\n  constexpr int QT = DP / (4 * C);        // pooler float4 groups per CTA\n  __shared__ float red[(NT / 32)];\n  __shared__ float slots[C];\n  __shared__ float score_all[NE];\n  __shared__ uint32_t ord_all[NE];\n  pdl_release();\n  cg::cluster_group cl = cg::this_cluster();\n  const int rank = (int)cl.block_rank(), t = blockIdx.y, tid = threadIdx.x;\n  constexpr int GQ = (QT + NT - 1) / NT;\n  float4 w[GQ];\n#pragma unroll\n  for (int g = 0; g < GQ; ++g) {\n    const int q = g * NT + tid;\n    w[g] = q < QT ? *reinterpret_cast<const float4*>(prew + (rank * QT + q) * 4) : make_float4(0.f, 0.f, 0.f, 0.f);\n  }\n  const int e = rank * EP + tid;\n  const float bs = tid < EP ? bias[e] : 0.f;\n  const int start = *lstart;\n  pdl_wait();\n  float4 p[GQ];\n  float v[1] = {0.f};\n#pragma unroll\n  for (int g = 0; g < GQ; ++g) {\n    const int q = g * NT + tid;\n    p[g] = q < QT ? sum_splits(P, pf32, S, ps, (long long)t * rs + (rank * QT + q) * 4) : make_float4(0.f, 0.f, 0.f, 0.f);\n    v[0] += p[g].x * p[g].x + p[g].y * p[g].y + p[g].z * p[g].z + p[g].w * p[g].w;\n  }\n  if (tid < EP) {  // logit: per split hi + lo, accumulated over splits (S6 order)\n    const long long base = (long long)t * rs + DP + e;\n    float logit = 0.f;\n    for (int s0 = 0; s0 < S; s0 += 8) {\n      float hi[8], lo[8];\n#pragma unroll\n      for (int u = 0; u < 8; ++u) {\n        hi[u] = lo[u] = 0.f;\n        if (s0 + u < S) {\n          const long long o = (s0 + u) * ps + base;\n          if (pf32) { hi[u] = static_cast<const float*>(P)[o]; lo[u] = static_cast<const float*>(P)[o + NE]; }\n          else { hi[u] = __bfloat162float(static_cast<const __nv_bfloat16*>(P)[o]); lo[u] = __bfloat162float(static_cast<const __nv_bfloat16*>(P)[o + NE]); }\n        }\n      }\n#pragma unroll\n      for (int u = 0; u < 8; ++u) logit += hi[u] + lo[u];\n    }\n    const float sc = 1.f / (1.f + __expf(-logit * 0.1767766952966369f));\n    float* rs_ = cl.map_shared_rank(score_all, 0);\n    uint32_t* ro = cl.map_shared_rank(ord_all, 0);\n    rs_[e] = sc;\n    ro[e] = route_ord(sc + bs);\n  }\n  block_sum<1, NT>(v, red);\n  cluster_sum<1, C>(cl, v, slots);   // its barrier also publishes the scores and keys to rank 0\n  const float inv = rsqrtf(v[0] / DP + 1e-5f);\n#pragma unroll\n  for (int g = 0; g < GQ; ++g) {\n    const int q = g * NT + tid;\n    if (q < QT) {\n      __nv_bfloat162 o0 = __floats2bfloat162_rn(p[g].x * inv * w[g].x, p[g].y * inv * w[g].y);\n      __nv_bfloat162 o1 = __floats2bfloat162_rn(p[g].z * inv * w[g].z, p[g].w * inv * w[g].w);\n      *reinterpret_cast<uint2*>(X + (long long)t * DP + (rank * QT + q) * 4) =\n          make_uint2(*reinterpret_cast<uint32_t*>(&o0), *reinterpret_cast<uint32_t*>(&o1));\n    }\n  }\n  if (rank == 0 && tid < 32) {  // top-8 over 256: 8 per lane; per round redux max of the key, ties to min id\n    const int lane = tid;\n    uint32_t k[8];\n#pragma unroll\n    for (int i = 0; i < 8; ++i) k[i] = ord_all[lane * 8 + i];\n    int pick[8];\n    float sc[8], tot = 0.f;\n#pragma unroll\n    for (int r = 0; r < 8; ++r) {\n      uint32_t bo = k[0];\n      int bi = 0;\n#pragma unroll\n      for (int i = 1; i < 8; ++i)\n        if (k[i] > bo) { bo = k[i]; bi = i; }\n      const uint32_t top = __reduce_max_sync(0xffffffffu, bo);\n      const int ex = (int)__reduce_min_sync(0xffffffffu, bo == top ? (uint32_t)(lane * 8 + bi) : 0xffffffffu);\n#pragma unroll\n      for (int i = 0; i < 8; ++i)\n        if (lane * 8 + i == ex) k[i] = 0u;\n      pick[r] = ex;\n      sc[r] = score_all[ex];\n    }\n#pragma unroll\n    for (int r = 0; r < 8; ++r) tot += sc[r];\n    if (lane < 8) {\n      int ex = pick[0];\n      float s = sc[0];\n#pragma unroll\n      for (int r = 1; r < 8; ++r) if (lane == r) { ex = pick[r]; s = sc[r]; }\n      ids[t * 8 + lane] = ex;\n      wts[t * 8 + lane] = s / (tot + 1e-15f);\n      const int local = (ex - start + 256) % 256;\n      lids[t * 8 + lane] = local < 32 ? local : -1;\n    }\n  }\n  if (meta != nullptr && rank == 0) {  // last-arriving token\'s rank-0 CTA writes MoERouteMeta (no CTA waits)\n    __shared__ int last;\n    __syncthreads();\n    if (tid == 0) {\n      __threadfence();\n      last = atomicAdd(arrive, 1u) == (unsigned)(gridDim.y - 1);\n      if (last) __threadfence();\n    }\n    __syncthreads();\n    if (last) {\n      write_route_meta(lids, (int)gridDim.y, start, meta);\n      if (tid == 0) *arrive = 0u;\n    }\n  }\n}\n\ntemplate <typename K>\nstatic void set_attrs(K kernel) {\n  static bool done = false;\n  if (!done) {\n    cudaFuncSetAttribute(kernel, cudaFuncAttributeNonPortableClusterSizeAllowed, 1);\n    done = true;\n  }\n}\n\ntemplate <typename K, typename... A>\nstatic cudaError_t launch(K kernel, int C, int NT, int T, cudaStream_t s, A... args) {\n  cudaLaunchConfig_t cfg = {};\n  cfg.gridDim = dim3(C, T, 1);\n  cfg.blockDim = dim3(NT, 1, 1);\n  cfg.stream = s;\n  cudaLaunchAttribute at[2];\n  at[0].id = cudaLaunchAttributeClusterDimension;\n  at[0].val.clusterDim.x = C;\n  at[0].val.clusterDim.y = 1;\n  at[0].val.clusterDim.z = 1;\n  at[1].id = cudaLaunchAttributeProgrammaticStreamSerialization;\n  at[1].val.programmaticStreamSerializationAllowed = 1;\n  cfg.attrs = at;\n  cfg.numAttrs = 2;\n  return cudaLaunchKernelEx(&cfg, kernel, args...);\n}\n\n}  // namespace glue_cl\n\n#define GLUE_B(C_, NT_, R_)                                                                                   \\\n  if (C == C_ && NT == NT_ && rounds == R_) {                                                                \\\n    auto k = glue_cl::boundary_cl<C_, NT_, R_>;                                                              \\\n    glue_cl::set_attrs(k);                                                                                   \\\n    e = glue_cl::launch(k, C, NT, (int)T, s, (const void*)P, (int)pf32, (int)S, (long long)ps, (long long)rs, \\\n                        (int)NB, (const float*)stream, (float*)sout, (__nv_bfloat16*)out, (const float*)postw,   \\\n                        (const float*)alpha, (const float*)beta, (const float*)prew);                          \\\n  }\n\nvoid boundary_cl(int64_t P, int64_t pf32, int64_t S, int64_t ps, int64_t rs, int64_t NB, int64_t stream, int64_t sout,\n                 int64_t out, int64_t postw, int64_t alpha, int64_t beta, int64_t prew, int64_t T, int64_t C, int64_t NT,\n                 int64_t rounds, int64_t stream_handle) {\n  cudaStream_t s = reinterpret_cast<cudaStream_t>(stream_handle);\n  cudaError_t e = cudaErrorInvalidValue;\n  GLUE_B(16, 128, 1) GLUE_B(16, 128, 2) GLUE_B(8, 256, 1) GLUE_B(8, 256, 2) GLUE_B(8, 128, 1) GLUE_B(8, 128, 2)\n  GLUE_B(4, 256, 1) GLUE_B(4, 256, 2) GLUE_B(4, 512, 1) GLUE_B(4, 512, 2) GLUE_B(2, 512, 1) GLUE_B(2, 512, 2)\n  GLUE_B(2, 256, 1) GLUE_B(2, 256, 2)\n  if (e != cudaSuccess) {\n    cudaGetLastError();  // a rejected launch (e.g. cluster size) must not poison later launches\n    throw std::runtime_error(cudaGetErrorString(e));\n  }\n}\n\n#define GLUE_R(C_, NT_)                                                                                        \\\n  if (C == C_ && NT == NT_) {                                                                                 \\\n    auto k = glue_cl::route_cl<C_, NT_>;                                                                      \\\n    glue_cl::set_attrs(k);                                                                                    \\\n    e = glue_cl::launch(k, C, NT, (int)T, s, (const void*)P, (int)pf32, (int)S, (long long)ps, (long long)rs, \\\n                        (const float*)bias, (const float*)prew, (const int*)lstart, (__nv_bfloat16*)X, (int*)ids, \\\n                        (float*)wts, (int*)lids, (glue_cl::MoERouteMeta*)meta, (unsigned*)arrive);             \\\n  }\n\nvoid route_cl(int64_t P, int64_t pf32, int64_t S, int64_t ps, int64_t rs, int64_t bias, int64_t prew, int64_t lstart,\n              int64_t X, int64_t ids, int64_t wts, int64_t lids, int64_t meta, int64_t arrive, int64_t T, int64_t C,\n              int64_t NT, int64_t stream_handle) {\n  cudaStream_t s = reinterpret_cast<cudaStream_t>(stream_handle);\n  cudaError_t e = cudaErrorInvalidValue;\n  if (meta && (NT != 256 || T > 32)) throw std::runtime_error("route_cl metadata: NT 256 and T <= 32");\n  GLUE_R(16, 128) GLUE_R(8, 128) GLUE_R(8, 256) GLUE_R(4, 256) GLUE_R(2, 256)\n  if (e != cudaSuccess) {\n    cudaGetLastError();  // a rejected launch (e.g. cluster size) must not poison later launches\n    throw std::runtime_error(cudaGetErrorString(e));\n  }\n}\n'
GP_CPP = '\n#include <cstdint>\nvoid boundary_cl(int64_t P, int64_t pf32, int64_t S, int64_t ps, int64_t rs, int64_t NB, int64_t stream, int64_t sout,\n                 int64_t out, int64_t postw, int64_t alpha, int64_t beta, int64_t prew, int64_t T, int64_t C, int64_t NT,\n                 int64_t rounds, int64_t stream_handle);\nvoid route_cl(int64_t P, int64_t pf32, int64_t S, int64_t ps, int64_t rs, int64_t bias, int64_t prew, int64_t lstart,\n              int64_t X, int64_t ids, int64_t wts, int64_t lids, int64_t meta, int64_t arrive, int64_t T, int64_t C,\n              int64_t NT, int64_t stream_handle);\n'

@triton.jit
def _l2_prefetch(ptrs):
    return tl.inline_asm_elementwise("prefetch.global.L2 [$1]; mov.u32 $0, 0;", "=r,l", [ptrs],
                                     dtype=tl.int32, is_pure=False, pack=1)

@triton.jit
def _pdl_start(USE: tl.constexpr):
    if USE:
        tl.extra.cuda.gdc_launch_dependents()

@triton.jit
def _pdl_wait(USE: tl.constexpr):
    if USE:
        tl.extra.cuda.gdc_wait()

@triton.jit
def _gemv_kernel(X, W, P, T, x_stride,
                 N: tl.constexpr, K: tl.constexpr, KS: tl.constexpr, BN: tl.constexpr,
                 BK: tl.constexpr, TB: tl.constexpr, PREFETCH: tl.constexpr, USE_PDL: tl.constexpr):
    pn = tl.program_id(0)
    ps = tl.program_id(1)
    _pdl_start(USE_PDL)
    n = pn * BN + tl.arange(0, BN)
    k0 = ps * KS
    if PREFETCH:
        lines = tl.arange(0, KS // 64)
        _l2_prefetch(W + n[:, None] * K + k0 + lines[None, :] * 64)
    _pdl_wait(USE_PDL)
    t = tl.arange(0, TB)
    kk = tl.arange(0, BK)
    acc = tl.zeros((BN, TB), tl.float32)
    for k in range(k0, k0 + KS, BK):
        w = tl.load(W + n[:, None] * K + (k + kk)[None, :])
        x = tl.load(X + t[:, None] * x_stride + (k + kk)[None, :], mask=t[:, None] < T, other=0.0)
        acc = tl.dot(w, tl.trans(x), acc)
    tl.store(P + ps * (T * N) + t[None, :] * N + n[:, None], acc, mask=t[None, :] < T)


import statistics
import time

import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline as _gp_load

# S8's decode chain O (cuBLAS stand-in) -> boundary 1 (cluster glue, releases at entry) -> pool_router GEMV (PDL)
# -> route (cluster) -> PDL consumer. S8's GEMV CTAs launch early but load nothing before griddepcontrol.wait;
# here the balanced split-K GEMV loads its first PRE weight tiles into registers (or L2-prefetches them) before
# the wait, so that part of the 75.5 MB stream overlaps boundary 1.


@triton.jit
def _gp_kernel(X, W, P, T, x_stride, N, K, S, BN: tl.constexpr, BK: tl.constexpr, TB: tl.constexpr,
               NS: tl.constexpr, PRE: tl.constexpr, L2: tl.constexpr):
    pn = tl.program_id(0)
    ps = tl.program_id(1)
    tl.extra.cuda.gdc_launch_dependents()
    n = pn * BN + tl.arange(0, BN)
    kb_total = K // BK
    kb0 = ps * kb_total // S
    kb1 = (ps + 1) * kb_total // S
    kk = tl.arange(0, BK)
    wrow = W + n[:, None] * K
    if L2 > 0:
        lines = tl.arange(0, L2 * BK // 64)
        _l2_prefetch(wrow + kb0 * BK + lines[None, :] * 64)
    if PRE >= 1:
        w0 = tl.load(wrow + (kb0 * BK + kk)[None, :])
    if PRE >= 2:
        w1 = tl.load(wrow + ((kb0 + 1) * BK + kk)[None, :])
    if PRE >= 3:
        w2 = tl.load(wrow + ((kb0 + 2) * BK + kk)[None, :])
    tl.extra.cuda.gdc_wait()
    t = tl.arange(0, TB)
    xrow = X + t[:, None] * x_stride
    tmask = t[:, None] < T
    acc = tl.zeros((BN, TB), tl.float32)
    if PRE >= 1:
        acc = tl.dot(w0, tl.trans(tl.load(xrow + (kb0 * BK + kk)[None, :], mask=tmask, other=0.0)), acc)
    if PRE >= 2:
        acc = tl.dot(w1, tl.trans(tl.load(xrow + ((kb0 + 1) * BK + kk)[None, :], mask=tmask, other=0.0)), acc)
    if PRE >= 3:
        acc = tl.dot(w2, tl.trans(tl.load(xrow + ((kb0 + 2) * BK + kk)[None, :], mask=tmask, other=0.0)), acc)
    for kb in tl.range(kb0 + PRE, kb1, num_stages=NS):
        k = kb * BK
        w = tl.load(wrow + (k + kk)[None, :])
        x = tl.load(xrow + (k + kk)[None, :], mask=tmask, other=0.0)
        acc = tl.dot(w, tl.trans(x), acc)
    tl.store(P + ps * (T * N) + t[None, :] * N + n[:, None], acc, mask=t[None, :] < T)


def gp_run(x, w, BN, S, PRE, L2, NS=4):
    T, K = x.shape
    N = w.shape[0]
    P = torch.empty((S, T, N), device=x.device, dtype=torch.float32)
    _gp_kernel[(N // BN, S)](x, w, P, T, x.stride(0), N, K, S, BN=BN, BK=128, TB=max(16, triton.next_power_of_2(T)),
                             NS=NS, PRE=PRE, L2=L2, num_warps=4, launch_pdl=True)
    return P, S


def gp_s8(x, w, cfg):
    T, K = x.shape
    N = w.shape[0]
    BN, KS, BK, pf = cfg
    S = K // KS
    P = torch.empty((S, T, N), device=x.device, dtype=torch.float32)
    _gemv_kernel[(N // BN, S)](x, w, P, T, x.stride(0), N=N, K=K, KS=KS, BN=BN, BK=BK,
                               TB=max(16, triton.next_power_of_2(T)), PREFETCH=pf, USE_PDL=True, launch_pdl=True,
                               num_warps=4, num_stages=4)
    return P, S


_GP_EXT = []


def gp_ext():
    if not _GP_EXT:
        major, minor = torch.cuda.get_device_capability()
        arch = '90a' if major == 9 else f'{major}{minor}'
        _GP_EXT.append(_gp_load(name=f'muse_lab_gemv_pre_{arch}', cpp_sources=GP_CPP, cuda_sources=GP_CUDA,
                                functions=['boundary_cl', 'route_cl'], verbose=False,
                                extra_cuda_cflags=['-O3', '-std=c++20', '--expt-relaxed-constexpr',
                                                   f'-gencode=arch=compute_{arch},code=sm_{arch}']))
    return _GP_EXT[0]


@triton.jit
def _gp_consume(A, B, S, NA: tl.constexpr, NB_: tl.constexpr):
    tl.extra.cuda.gdc_launch_dependents()
    tl.extra.cuda.gdc_wait()
    t = tl.program_id(0)
    a = tl.load(A + t * NA + tl.arange(0, NA)).to(tl.float32)
    b = tl.load(B + t * NB_ + tl.arange(0, NB_)).to(tl.float32)
    tl.store(S + t, tl.sum(a * a, 0) + tl.sum(b, 0))


@triton.jit
def _gp_sink(A, S, N: tl.constexpr, NP: tl.constexpr):
    tl.extra.cuda.gdc_launch_dependents()
    tl.extra.cuda.gdc_wait()
    t = tl.program_id(0)
    c = tl.arange(0, NP)
    a = tl.load(A + t * N + c, mask=c < N, other=0.0).to(tl.float32)
    tl.store(S + t, tl.sum(a * a, 0))


@triton.jit
def _gp_sumcast(P, Y, PS, N: tl.constexpr, S: tl.constexpr, BLOCK: tl.constexpr):
    """patch_front_bf16's _attn_sumcast_kernel (PDL; split order; one rounding)."""
    t = tl.program_id(0)
    b = tl.program_id(1)
    tl.extra.cuda.gdc_launch_dependents()
    tl.extra.cuda.gdc_wait()
    c = b * BLOCK + tl.arange(0, BLOCK)
    acc = tl.zeros([BLOCK], tl.float32)
    for s in tl.static_range(S):
        acc += tl.load(P + s * PS + t * N + c, mask=c < N, other=0.0)
    tl.store(Y + t * N + c, acc.to(tl.bfloat16), mask=c < N)


class GPQkv:
    """qkv producer -> BF16 qkv (sum+cast kernel for split partials) -> PDL sink. `rows` limits the weight to
    its first rows (1280 = q, k, v without the gate)."""

    def __init__(self, t, x, prod, n):
        self.t, self.x, self.prod, self.n = t, x, prod, n
        self.sink = torch.empty(t, device=x.device, dtype=torch.float32)

    def __call__(self):
        p, s = self.prod(self.x)
        if p.dtype == torch.float32:
            y = torch.empty((self.t, self.n), device=p.device, dtype=torch.bfloat16)
            _gp_sumcast[(self.t, triton.cdiv(self.n, 512))](p, y, p.stride(0), N=self.n, S=s, BLOCK=512,
                                                            launch_pdl=True, num_warps=4)
        else:
            y = p[0]
        _gp_sink[(self.t,)](y, self.sink, N=self.n, NP=triton.next_power_of_2(self.n), launch_pdl=True, num_warps=4)
        return (y,)


class GPUnpool:
    """unpooler producer -> boundary_cl b2 ('cl', 8, 256, 1; NB 8192, post-FFN weight) -> PDL sink."""

    def __init__(self, t, x, v, prod):
        self.t, self.x, self.v, self.prod = t, x, v, prod
        self.sink = torch.empty(t, device=x.device, dtype=torch.float32)

    def __call__(self):
        t, v = self.t, self.v
        p, s = self.prod(self.x)
        out = torch.empty((t, 8192), device=p.device, dtype=torch.bfloat16)
        sout = torch.empty_like(v['stream'])
        gp_ext().boundary_cl(p.data_ptr(), int(p.dtype == torch.float32), s, p.stride(0), p.stride(1), p.shape[2],
                             v['stream'].data_ptr(), sout.data_ptr(), out.data_ptr(), v['post_ffn_w'].data_ptr(),
                             v['alpha1'].data_ptr(), v['beta1'].data_ptr(), v['pre_ffn_w'].data_ptr(), t, 8, 256, 1,
                             torch.cuda.current_stream().cuda_stream)
        _gp_sink[(t,)](out, self.sink, N=8192, NP=8192, launch_pdl=True, num_warps=8)
        return (out, sout)


class GPChain:
    """O (F.linear, S8's cuBLAS kind at t >= 16 / stand-in at t = 1) -> boundary_cl ('cl', 8, 256, 1) ->
    pool_router producer -> route_cl ('cl', 8, 256, 0) -> consumer."""

    def __init__(self, t, v, attn, prod):
        self.t, self.v, self.attn, self.prod = t, v, attn, prod
        self.sink = torch.empty(t, device=attn.device, dtype=torch.float32)

    def __call__(self):
        t, v, ext, st = self.t, self.v, gp_ext(), torch.cuda.current_stream().cuda_stream
        o = F.linear(self.attn, v['o']).unsqueeze(0)
        h = torch.empty((t, 8192), device=o.device, dtype=torch.bfloat16)
        sout = torch.empty_like(v['stream'])
        ext.boundary_cl(o.data_ptr(), 0, 1, o.stride(0), o.stride(1), 8192, v['stream'].data_ptr(), sout.data_ptr(),
                        h.data_ptr(), 0, v['alpha1'].data_ptr(), v['beta1'].data_ptr(), v['pre_ffn_w'].data_ptr(), t, 8,
                        256, 1, st)
        p, s = self.prod(h)
        x = torch.empty((t, 4096), device=o.device, dtype=torch.bfloat16)
        ids = torch.empty((t, 8), device=o.device, dtype=torch.int32)
        wts = torch.empty((t, 8), device=o.device, dtype=torch.float32)
        lids = torch.empty_like(ids)
        ext.route_cl(p.data_ptr(), 1, s, p.stride(0), p.stride(1), v['bias'].data_ptr(), v['pre_expert_w'].data_ptr(),
                     v['lstart'].data_ptr(), x.data_ptr(), ids.data_ptr(), wts.data_ptr(), lids.data_ptr(), 0, 0, t, 8,
                     256, st)
        _gp_consume[(t,)](x, wts, self.sink, NA=4096, NB_=8, launch_pdl=True, num_warps=4)
        return x, ids, wts


def _gp_graph(fn):
    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s):
        for _ in range(2):
            fn()
    torch.cuda.current_stream().wait_stream(s)
    torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        out = fn()
    g.replay()
    torch.cuda.synchronize()
    return g, out


def _gp_times(graphs, rounds):
    evs = []
    for r in range(rounds):
        order = list(range(len(graphs)))
        if r % 2:
            order.reverse()
        for j in order:
            lab_cold_l2()  # h200_lab: the judge's cold-L2 step (1 GiB read)
            a, b = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
            a.record()
            graphs[j].replay()
            b.record()
            evs.append((j, a, b))
    torch.cuda.synchronize()
    vals = [[] for _ in graphs]
    for j, a, b in evs:
        vals[j].append(a.elapsed_time(b) * 1e3)
    return vals


def _gp_vectors(weights, dev, gen, t):
    def gate(n):
        w = (torch.randn(n, device=dev, generator=gen) * 0.5).float() / 0.3
        beta = torch.sigmoid(w)
        return torch.sqrt(torch.clamp(torch.sigmoid(-w) * (1.0 + beta), min=1e-3)).contiguous(), beta.contiguous()
    a1, b1 = gate(8192)
    norm = lambda n: (1.0 + 0.1 * torch.randn(n, device=dev, generator=gen)).float().contiguous()  # noqa: E731
    router = weights['router'].float()
    hi = router.to(torch.bfloat16)
    return dict(alpha1=a1, beta1=b1, pre_ffn_w=norm(8192), pre_expert_w=norm(4096), post_ffn_w=norm(8192),
                bias=(0.01 * torch.randn(256, device=dev, generator=gen)).float().contiguous(),
                lstart=torch.tensor([96], device=dev, dtype=torch.int32), o=weights['o'].contiguous(),
                stream=torch.randn((t, 8192), device=dev, generator=gen).float(),
                pool_router=torch.cat([weights['pooler'], hi, (router - hi.float()).to(torch.bfloat16)], 0).contiguous(),
                qkv=weights['qkv_gate'].contiguous(), unpooler=weights['unpooler'].contiguous())


# S8's choices per tokens: pool_router V9_union cfg; qkv V9 tile (t <= 16) or cuBLAS (t = 32, prepare tuner);
# unpooler cuBLAS. Balanced winners from gemv_bal 26fd09a7: pool_router 64/6, qkv 64/7, unpooler 64/2.
GP_S8 = {1: (32, 1024, 128, False), 16: (32, 1024, 128, False), 32: (64, 512, 128, False)}
GP_QKV_S8 = {1: (32, 1024, 128, False), 16: (32, 1024, 128, False), 32: 'cublas'}


def _gp_paired(graphs, rounds):
    vals = _gp_times(graphs, rounds)
    base = vals[0]
    res = []
    for vv in vals:
        pairs = [(vv[i] + vv[i + 1]) / (base[i] + base[i + 1]) for i in range(0, len(vv) - 1, 2)]
        res.append((statistics.median(vv), statistics.median(pairs)))
    return res


def _gp_case(lines, tag, t, arms, make, ref_idx=0, check=None):
    chains = [make(prod) for _, prod in arms]
    graphs, outs = [], []
    for ch in chains:
        g, out = _gp_graph(ch)
        graphs.append(g)
        outs.append(out)
    bad = []
    if check is not None:
        for (name, _), out in zip(arms, outs):
            msg = check(out, outs[ref_idx])
            if msg:
                bad.append(f'{name}:{msg}')
    res = _gp_paired(graphs, 24)
    cells = ' '.join(f'[{n} {u:.2f}us r={r:.4f}]' for (n, _), (u, r) in zip(arms[2:], res[2:]))
    lines.append(f'{tag} t={t} {arms[0][0]}={res[0][0]:.2f}us AA={res[1][1]:.4f} {cells}' + (f' BAD {" ".join(bad)}' if bad else ''))
    del graphs, chains


def lab(deadline, weights):
    t0 = time.monotonic()
    dev = weights['o'].device
    gen = torch.Generator(device=dev).manual_seed(5)
    lines = ['META paired chains, lab_cold_l2 per replay, r = paired median vs the first arm, AA = control vs itself. '
             'POOL: O (F.linear) -> boundary_cl b1 -> pool_router -> route_cl -> sink; s8 = S8 V9_union GEMV; bBN/S = '
             'balanced split-K, pN = N weight tiles in registers / lN = N tiles L2-prefetched before griddepcontrol.wait. '
             'QKV: qkv producer -> sum+cast (split partials) -> sink; s8 = V9 tile (t<=16) / cuBLAS (t=32). SPLIT: '
             'q,k,v rows only (qkv3, 1280) and gate rows only (1024) in the same chain (medians; the gate split\'s '
             'critical path). UNPOOL: unpooler producer -> boundary_cl b2 -> sink; control cuBLAS (S8).']
    rel = lambda a, b: float((a.float() - b.float()).norm() / b.float().norm().clamp_min(1e-12))  # noqa: E731
    for t in (1, 16, 32):
        if time.monotonic() > deadline - 30:
            lines.append(f'SKIP t={t}')
            continue
        try:
            v = _gp_vectors(weights, dev, gen, t)
            attn = (torch.randn((t, 1024), device=dev, generator=gen) * 0.5).to(torch.bfloat16)
            w = v['pool_router']
            arms = [('s8', lambda x: gp_s8(x, w, GP_S8[t])), ('s8b', lambda x: gp_s8(x, w, GP_S8[t]))]
            for name, BN, S, PRE, L2 in (('b64/6', 64, 6, 0, 0), ('b64/6p1', 64, 6, 1, 0), ('b64/6p2', 64, 6, 2, 0),
                                         ('b64/6l4', 64, 6, 0, 4), ('b32/3', 32, 3, 0, 0)):
                arms.append((name, lambda x, BN=BN, S=S, PRE=PRE, L2=L2: gp_run(x, w, BN, S, PRE, L2)))
            _gp_case(lines, 'POOL', t, arms, lambda prod: GPChain(t, v, attn, prod),
                     check=lambda o, r: '' if torch.equal(o[1], r[1]) and rel(o[0], r[0]) < 1e-2 else f'ids={torch.equal(o[1], r[1])},x={rel(o[0], r[0]):.1e}')
        except Exception as exc:
            lines.append(f'ERROR POOL t={t} {type(exc).__name__}: {str(exc).splitlines()[0][:160]}')
        try:
            wq = v['qkv']
            x = (torch.randn((t, 8192), device=dev, generator=gen) * 0.5).to(torch.bfloat16)
            ctrl = GP_QKV_S8[t]
            s8 = (lambda x: (F.linear(x, wq).unsqueeze(0), 1)) if ctrl == 'cublas' else (lambda x: gp_s8(x, wq, ctrl))
            arms = [('s8', s8), ('s8b', s8), ('b64/7', lambda x: gp_run(x, wq, 64, 7, 0, 0)),
                    ('b32/7', lambda x: gp_run(x, wq, 32, 7, 0, 0))]
            _gp_case(lines, 'QKV', t, arms, lambda prod: GPQkv(t, x, prod, 2304),
                     check=lambda o, r: '' if rel(o[0], r[0]) < 1e-2 else f'y={rel(o[0], r[0]):.1e}')
            # the gate split's critical path: q, k, v rows only (1280), and the gate rows alone (1024)
            wqkv, wg = wq[:1280], wq[1280:]
            arms = [('s8', s8), ('s8b', s8), ('qkv3_b64/10', lambda x: gp_run(x, wqkv, 64, 10, 0, 0)),
                    ('qkv3_b32/7', lambda x: gp_run(x, wqkv, 32, 7, 0, 0)), ('qkv3_b32/12', lambda x: gp_run(x, wqkv, 32, 12, 0, 0)),
                    ('gate_b64/8', lambda x: gp_run(x, wg, 64, 8, 0, 0))]
            chains = [GPQkv(t, x, prod, 2304 if not name.startswith(('qkv3', 'gate')) else (1280 if name.startswith('qkv3') else 1024))
                      for name, prod in arms]
            graphs = [_gp_graph(ch)[0] for ch in chains]
            res = _gp_paired(graphs, 24)
            lines.append(f'SPLIT t={t} s8={res[0][0]:.2f}us AA={res[1][1]:.4f} ' +
                         ' '.join(f'[{n} {u:.2f}us]' for (n, _), (u, _r) in zip(arms[2:], res[2:])))
            del graphs, chains
        except Exception as exc:
            lines.append(f'ERROR QKV t={t} {type(exc).__name__}: {str(exc).splitlines()[0][:160]}')
        if t == 1:
            continue
        try:
            wu = v['unpooler']
            xu = (torch.randn((t, 4096), device=dev, generator=gen) * 0.5).to(torch.bfloat16)
            cub = lambda x: (F.linear(x, wu).unsqueeze(0), 1)  # noqa: E731
            arms = [('cublas', cub), ('cublas_b', cub), ('b64/2', lambda x: gp_run(x, wu, 64, 2, 0, 0)),
                    ('b32/1', lambda x: gp_run(x, wu, 32, 1, 0, 0))]
            _gp_case(lines, 'UNPOOL', t, arms, lambda prod: GPUnpool(t, xu, v, prod),
                     check=lambda o, r: '' if rel(o[1], r[1]) < 1e-2 else f'sout={rel(o[1], r[1]):.1e}')
        except Exception as exc:
            lines.append(f'ERROR UNPOOL t={t} {type(exc).__name__}: {str(exc).splitlines()[0][:160]}')
        torch.cuda.empty_cache()
    lines.append(f'END t={time.monotonic() - t0:.1f}s')
    return lines
